import { useState, useEffect } from 'react';
import { useAuth } from '@/hooks/useAuth';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import { Navigate, useNavigate } from 'react-router-dom';
import { Loader2, Wrench } from 'lucide-react';

// ===========================================================
// PASSO 1: Vá em um conversor de Imagem para Base64
// PASSO 2: Cole o código gigante gerado dentro das aspas abaixo
// ===========================================================
const imagemBase64 = "data:image/jpeg;base64,";

const Auth = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [checkingAuth, setCheckingAuth] = useState(true);
  const { signIn, user, session } = useAuth();
  const { toast } = useToast();
  const navigate = useNavigate();

  useEffect(() => {
    const checkAuthentication = async () => {
      if (user && session) {
        navigate('/');
        return;
      }
      setCheckingAuth(false);
    };

    checkAuthentication();
  }, [user, session, navigate]);

  if (checkingAuth) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-slate-50">
        <div className="text-center">
          <Loader2 className="h-12 w-12 animate-spin text-orange-500 mx-auto mb-4" />
          <p className="text-slate-500 text-lg">Verificando autenticação...</p>
        </div>
      </div>
    );
  }

  if (user && session) {
    return <Navigate to="/" replace />;
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const { error } = await signIn(email, password);
      if (error) {
        toast({
          title: "Erro no Login",
          description: error.message === 'Invalid login credentials' 
            ? "Email ou senha incorretos" 
            : error.message,
          variant: "destructive"
        });
      } else {
        toast({
          title: "Login realizado com sucesso!",
          description: "Bem-vindo ao sistema"
        });
      }
    } catch (error) {
      toast({
        title: "Erro",
        description: "Ocorreu um erro inesperado",
        variant: "destructive"
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex min-h-screen">
      {/* Painel lateral esquerdo - Imagem via Código Base64 */}
      <div 
        className="hidden flex-1 flex-col justify-between p-12 text-slate-400 lg:flex relative overflow-hidden"
        style={{
          backgroundImage: `url(${imagemBase64})`, // Usamos a variável com o código aqui
          backgroundSize: 'cover',
          backgroundPosition: 'center',
          backgroundRepeat: 'no-repeat',
        }}
      >
        {/* Camada escura semi-transparente (Overlay) */}
        <div className="absolute inset-0 bg-slate-950/85 z-0 pointer-events-none" />

        {/* Conteúdo com z-10 para ficar acima do overlay */}
        <div className="relative z-10 flex items-center gap-2">
          <Wrench className="h-6 w-6 text-orange-500" />
          <span className="font-display text-lg font-bold text-white uppercase tracking-wide">relatorio operacional</span>
        </div>

        <div className="relative z-10">
          <h1 className="font-display text-5xl font-bold leading-tight text-white drop-shadow-md">
            Controle total das <span className="text-orange-500">Operações</span>.
          </h1>
          <p className="mt-4 max-w-md text-slate-300 text-lg drop-shadow-sm">
            Visualize e exporte relatórios em um único painel — projetado por Mattos Mias
          </p>
        </div>

        <p className="text-xs text-slate-500 relative z-10">© Mattos Matias Dias</p>
      </div>

      {/* Área do formulário */}
      <div className="flex flex-1 items-center justify-center bg-slate-50 p-6">
        <Card className="w-full max-w-md p-8 shadow-xl border-slate-200">
          <CardHeader className="p-0 space-y-1">
            <CardTitle className="font-display text-2xl font-bold text-slate-900">Entrar</CardTitle>
            <p className="mt-1 text-sm text-slate-500">Acesse sua conta para continuar.</p>
          </CardHeader>
          <CardContent className="p-0 mt-6">
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="email" className="text-slate-700">Email</Label>
                <Input
                  id="email"
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                  disabled={loading}
                  placeholder="seu@email.com"
                  className="bg-white border-slate-300 text-slate-900 focus-visible:ring-orange-500"
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="password" className="text-slate-700">Senha</Label>
                <Input
                  id="password"
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                  disabled={loading}
                  placeholder="Sua senha"
                  className="bg-white border-slate-300 text-slate-900 focus-visible:ring-orange-500"
                />
              </div>
              <Button
                type="submit"
                className="w-full bg-orange-600 hover:bg-orange-700 text-white font-medium shadow-md"
                disabled={loading}
              >
                {loading ? (
                  <>
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    Entrando...
                  </>
                ) : (
                  'Entrar'
                )}
              </Button>
            </form>
            <p className="mt-6 text-xs text-slate-500 text-center">
              Não tem acesso? Solicite ao administrador.
            </p>
          </CardContent>
        </Card>
      </div>
    </div>
  );
};

export default Auth;